// Извлекаем текст вопроса и chat_id из сообщения Telegram
const msg = $input.first().json;
const chatId = msg.message?.chat?.id || msg.callback_query?.message?.chat?.id;
const text = (msg.message?.text || '').trim();

if (!text || text === '/start') {
  return [{
    json: {
      chatId,
      text,
      action: 'welcome'
    }
  }];
}

return [{
  json: {
    chatId,
    text,
    action: 'question'
  }
}];

// Собираем контекст из найденных чанков
const items = $input.all();
const chunks = items.map((item, i) => {
  const doc = item.json;
  const text = doc.pageContent || doc.text || doc.content || JSON.stringify(doc);
  const source = doc.metadata?.source || doc.metadata?.title || `Чанк ${i + 1}`;
  const score = doc.score ? ` (релевантность: ${(doc.score * 100).toFixed(1)}%)` : '';
  return `[${source}${score}]\n${text}`;
}).filter(c => c.length > 0);

const context = chunks.join('\n\n---\n\n');
const question = $('Parse Input').first().json.text;
const chatId = $('Parse Input').first().json.chatId;

return [{
  json: {
    chatId,
    question,
    context,
    chunkCount: chunks.length
  }
}];

