// Логируем запрос и ответ для аналитики
const now = new Date().toISOString();
const question = $('Parse Input').first().json.text;
const chatId = $('Parse Input').first().json.chatId;
const chunkCount = $('Build RAG Context').first().json.chunkCount;
const answer = $('Generate Answer (GPT-4o)').first().json.message?.content || $('Generate Answer (GPT-4o)').first().json.text || '';

return [{
  json: {
    timestamp: now,
    chat_id: chatId,
    question: question,
    chunks_found: chunkCount,
    answer_length: answer.length,
    answer_preview: answer.substring(0, 200) + (answer.length > 200 ? '...' : '')
  }
}];
